# ---- 公共函数 ----
def _t(s):
    return datetime.strptime(s, "%Y-%m-%d %H:%M") if s else None


NOW = _t(DEMO_NOW)


def _fmt(dt):
    return dt.strftime("%m月%d日 %H:%M")


def _find(order_id, buyer_id, shop):
    """按 订单号 + 买家ID + 店铺 查订单。三者对不上一律当作"没查到"，不泄露别人的订单是否存在。"""
    oid = (order_id or "").strip().upper()
    if not oid:
        return None, "NO_ORDER_ID"
    o = ORDERS.get(oid)
    if (not o) or o["buyer_id"] != (buyer_id or "").strip() or o["shop"] != (shop or "").strip():
        return None, "ORDER_NOT_FOUND"
    return o, None


def _ticket(order_id, ticket_type):
    """生成演示用工单号（同一订单同一类型得到同一个号，方便复现）。"""
    s = (order_id or "NA") + ticket_type
    h = 0
    for ch in s:
        h = (h * 31 + ord(ch)) % 1000000
    return "TK" + NOW.strftime("%m%d") + str(h).zfill(6)


# ---- 本节点逻辑 ----
def main(pending_action: str, buyer_id: str, shop: str) -> dict:
    try:
        p = json.loads(pending_action)
    except Exception:
        return {"answer": "没有找到待确认的修改，请重新告诉我订单号和新地址～"}
    o, err = _find(p.get("order_id"), buyer_id, shop)
    if err:
        return {"answer": "没有找到这个订单，地址没有修改。"}
    if o["status"] != "待发货":
        return {"answer": "抱歉，订单 " + o["order_id"] + " 刚刚已经发货，地址没能修改成功。可以回复「转人工」帮您联系快递改派。"}
    # 演示环境：这里只模拟"写入成功"，并不会真的改掉 ORDERS 里的数据
    return {"answer": "已为您把订单 " + o["order_id"] + " 的收货地址修改为：" + p.get("new_address", "") + "。仓库会按新地址发货～"}
